import struct

class Reader:
    def __init__(self, b): self.b=b; self.i=0
    def byte(self):
        v=self.b[self.i]; self.i+=1; return v
    def varint(self):
        shift=0; res=0
        while True:
            v=self.byte()
            res|=(v&0x7F)<<shift
            if not (v&0x80): break
            shift+=7
        return res
    def zigzag(self,n):
        return (n>>1) ^ -(n&1)
    def read(self):
        t=self.byte()
        ct=t&0x0F; delta=t>>4
        if delta==0:
            fid=self.zigzag(self.varint())
        else:
            fid=delta
        return fid, ct

